import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { css, cx } from "../../styled-system/css";
import { useReducedMotion } from "../hooks/use-media-query";
import { ShaderField } from "./ShaderField";

const srOnly = css({
  position: "absolute",
  width: "1px",
  height: "1px",
  margin: "-1px",
  padding: 0,
  border: 0,
  overflow: "hidden",
  whiteSpace: "nowrap",
  clipPath: "inset(50%)",
});

/* ------------------------------------------------------------------ *
 * Hero headline
 * ------------------------------------------------------------------ */

const HEADLINES = [
  "Say it in your own words.",
  "Find where it thins out.",
  "Rebuild it. Teach it back.",
];

const TYPE_MS = 42;
const ERASE_MS = 22;
const HOLD_MS = 2100;

/**
 * The hero's second line types itself, holds, erases, and moves on. The typed
 * span is hidden from assistive tech — the same promise is exposed once as
 * static text so screen readers don't hear it rebuilt character by character.
 */
export function AnimatedHeroHeadline() {
  const reducedMotion = useReducedMotion();
  const [index, setIndex] = useState(0);
  const [chars, setChars] = useState(HEADLINES[0].length);
  const [erasing, setErasing] = useState(false);

  useEffect(() => {
    if (reducedMotion) return;
    setIndex(0);
    setChars(0);
    setErasing(false);
  }, [reducedMotion]);

  useEffect(() => {
    if (reducedMotion) return;
    const phrase = HEADLINES[index];

    if (!erasing && chars < phrase.length) {
      const timer = setTimeout(() => setChars(chars + 1), TYPE_MS);
      return () => clearTimeout(timer);
    }
    if (!erasing) {
      const timer = setTimeout(() => setErasing(true), HOLD_MS);
      return () => clearTimeout(timer);
    }
    if (chars > 0) {
      const timer = setTimeout(() => setChars(chars - 1), ERASE_MS);
      return () => clearTimeout(timer);
    }
    const timer = setTimeout(() => {
      setErasing(false);
      setIndex((current) => (current + 1) % HEADLINES.length);
    }, 260);
    return () => clearTimeout(timer);
  }, [chars, erasing, index, reducedMotion]);

  const visible = reducedMotion ? HEADLINES[0] : HEADLINES[index].slice(0, chars);

  return (
    <h2
      className={cx(
        "hero-headline",
        css({
          display: "flex",
          alignItems: "center",
          minHeight: "2.4em",
          color: "var(--accent-dim)",
          _dark: { color: "var(--phosphor)" },
        }),
      )}
    >
      <span aria-hidden="true">
        {visible}
        <span className="cursor" />
      </span>
      <span className={srOnly}>
        Say it in your own words. Find where it thins out. Rebuild it and teach it back.
      </span>
    </h2>
  );
}

/* ------------------------------------------------------------------ *
 * Hero stage
 * ------------------------------------------------------------------ */

const tick = css({
  position: "absolute",
  width: "14px",
  height: "14px",
  borderColor: "var(--accent-dim)",
  opacity: 0.55,
  pointerEvents: "none",
});

/**
 * Frames whatever terminal the hero decides to render (flat or 3D) in a
 * shader-lit stage with technical-drawing corner ticks. The field drifts
 * against the pointer, which reads as depth without moving the terminal.
 */
export function HeroWonderStage({ children }: { children: ReactNode }) {
  const stageRef = useRef<HTMLDivElement>(null);
  const reducedMotion = useReducedMotion();

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || reducedMotion) return;
    if (!window.matchMedia("(pointer: fine)").matches) return;

    let frame = 0;
    let pending: { x: number; y: number } | null = null;

    function apply() {
      frame = 0;
      const next = pending;
      if (!next || !stage) return;
      stage.style.setProperty("--parallax-x", `${next.x.toFixed(2)}px`);
      stage.style.setProperty("--parallax-y", `${next.y.toFixed(2)}px`);
    }

    function onPointerMove(event: PointerEvent) {
      const rect = stage?.getBoundingClientRect();
      if (!rect || rect.width === 0) return;
      pending = {
        x: ((event.clientX - rect.left) / rect.width - 0.5) * -18,
        y: ((event.clientY - rect.top) / rect.height - 0.5) * -12,
      };
      if (!frame) frame = requestAnimationFrame(apply);
    }

    function onPointerLeave() {
      pending = { x: 0, y: 0 };
      if (!frame) frame = requestAnimationFrame(apply);
    }

    stage.addEventListener("pointermove", onPointerMove);
    stage.addEventListener("pointerleave", onPointerLeave);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      stage.removeEventListener("pointermove", onPointerMove);
      stage.removeEventListener("pointerleave", onPointerLeave);
    };
  }, [reducedMotion]);

  return (
    <div
      ref={stageRef}
      className={css({
        position: "relative",
        width: "100%",
        isolation: "isolate",
        "--parallax-x": "0px",
        "--parallax-y": "0px",
      })}
    >
      <div
        aria-hidden="true"
        className={css({
          position: "absolute",
          inset: "-14% -10%",
          zIndex: 0,
          transform: "translate3d(var(--parallax-x), var(--parallax-y), 0)",
          transition: "transform 420ms cubic-bezier(0.16, 1, 0.3, 1)",
        })}
      >
        <ShaderField colorVar="--phosphor" density={58} intensity={0.92} />
      </div>

      <span className={cx(tick, css({ top: 0, left: 0, borderTop: "2px solid", borderLeft: "2px solid" }))} aria-hidden="true" />
      <span className={cx(tick, css({ top: 0, right: 0, borderTop: "2px solid", borderRight: "2px solid" }))} aria-hidden="true" />
      <span className={cx(tick, css({ bottom: 0, left: 0, borderBottom: "2px solid", borderLeft: "2px solid" }))} aria-hidden="true" />
      <span className={cx(tick, css({ bottom: 0, right: 0, borderBottom: "2px solid", borderRight: "2px solid" }))} aria-hidden="true" />

      <div className={css({ position: "relative", zIndex: 1 })}>{children}</div>
    </div>
  );
}

/* ------------------------------------------------------------------ *
 * Kinetic teaching text
 * ------------------------------------------------------------------ */

const KINETIC_LEAD = "Most tools finish your sentence.";
const KINETIC_TURN = "Keating waits for you to finish the thought.";

/**
 * A dark band mid-page where the statement resolves out of the phosphor as you
 * scroll — each word carries its own index, and one CSS variable on the section
 * drives the whole reveal, so scrolling costs a single style write per frame.
 */
export function KineticTeachingText() {
  const sectionRef = useRef<HTMLElement>(null);
  const reducedMotion = useReducedMotion();
  const words = [...KINETIC_LEAD.split(" "), ...KINETIC_TURN.split(" ")];
  const leadCount = KINETIC_LEAD.split(" ").length;

  useEffect(() => {
    const section = sectionRef.current;
    if (!section) return;
    if (reducedMotion) {
      section.style.setProperty("--p", "1");
      return;
    }

    let frame = 0;
    function measure() {
      frame = 0;
      const el = sectionRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const viewport = window.innerHeight || 1;
      // Finish the reveal by the time the band sits in the middle of the screen.
      const span = viewport * 0.55 + rect.height * 0.45;
      const travelled = viewport * 0.92 - rect.top;
      const progress = Math.min(1, Math.max(0, travelled / Math.max(span, 1)));
      el.style.setProperty("--p", progress.toFixed(4));
    }

    function schedule() {
      if (!frame) frame = requestAnimationFrame(measure);
    }

    measure();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, [reducedMotion]);

  return (
    <section
      ref={sectionRef}
      aria-label="How Keating teaches"
      className={cx(
        "crt",
        css({
          position: "relative",
          overflow: "hidden",
          isolation: "isolate",
          borderBlock: "2px solid var(--ink)",
          background: "var(--terminal)",
          color: "var(--phosphor)",
          paddingBlock: { base: "5rem", md: "8.5rem" },
          "--p": 0,
          "--n": words.length,
        }),
      )}
      style={{ "--n": words.length } as CSSProperties}
    >
      <ShaderField colorVar="--phosphor" density={92} intensity={0.75} radial={false} />

      <div className={cx("wrap", css({ position: "relative", zIndex: 1 }))}>
        <p
          className={css({
            maxWidth: "20ch",
            margin: 0,
            fontFamily: "var(--mono-display)",
            fontWeight: 700,
            fontSize: { base: "2.1rem", md: "4.2rem" },
            lineHeight: 1.06,
            letterSpacing: "-0.03em",
            textWrap: "balance",
          })}
        >
          {words.map((word, i) => (
            <span
              key={`${word}-${i}`}
              style={{ "--i": i } as CSSProperties}
              className={css({
                display: "inline-block",
                marginRight: "0.28em",
                color: "var(--phosphor)",
                opacity: "clamp(0, calc((var(--p) * var(--n) - var(--i)) * 1.4), 1)",
                filter:
                  "blur(calc(clamp(0, calc(var(--i) + 1 - var(--p) * var(--n)), 1) * 7px))",
                transform:
                  "translateY(calc(clamp(0, calc(var(--i) + 1 - var(--p) * var(--n)), 1) * 0.3em))",
                textShadow: "0 0 26px color-mix(in srgb, var(--phosphor) 45%, transparent)",
                willChange: "opacity, filter, transform",
              })}
            >
              {i === leadCount ? <br className={css({ display: { base: "none", md: "block" } })} /> : null}
              {word}
            </span>
          ))}
        </p>

        <p
          className={css({
            maxWidth: "44ch",
            marginTop: { base: "1.75rem", md: "2.5rem" },
            marginBottom: 0,
            color: "var(--phosphor-dim)",
            fontFamily: "var(--mono-body)",
            fontSize: { base: "0.86rem", md: "0.98rem" },
            lineHeight: 1.75,
            opacity: "clamp(0, calc(var(--p) * 2 - 1), 1)",
            transition: "opacity 200ms linear",
          })}
        >
          Every session ends with you holding the explanation — not a transcript of someone else
          holding it for you.
        </p>
      </div>
    </section>
  );
}

/* ------------------------------------------------------------------ *
 * Learning journey
 * ------------------------------------------------------------------ */

const JOURNEY = [
  { step: "01", title: "Diagnose", body: "Keating maps what you already hold before it teaches anything." },
  { step: "02", title: "Dialogue", body: "You explain. It probes the seam where the explanation thins." },
  { step: "03", title: "Artifact", body: "The lesson leaves files: a plan, a map, a quiz you can read." },
  { step: "04", title: "Return", body: "It comes back before you forget, not after." },
];

/** Four beats of a session, drawn in as the row enters the viewport. */
export function LearningJourney() {
  const ref = useRef<HTMLDivElement>(null);
  const reducedMotion = useReducedMotion();
  const [revealed, setRevealed] = useState(false);

  useEffect(() => {
    if (reducedMotion) {
      setRevealed(true);
      return;
    }
    const el = ref.current;
    if (!el || !("IntersectionObserver" in window)) {
      setRevealed(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setRevealed(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [reducedMotion]);

  return (
    <section
      aria-labelledby="journey-title"
      className={css({
        borderBottom: "2px solid var(--ink)",
        background: "var(--paper)",
        paddingBlock: { base: "4rem", md: "6rem" },
      })}
    >
      <div className="wrap">
        <h2
          id="journey-title"
          className={css({
            maxWidth: "22ch",
            margin: "0 0 2.75rem",
            fontFamily: "var(--mono-display)",
            fontWeight: 700,
            fontSize: { base: "1.9rem", md: "2.9rem" },
            lineHeight: 1.05,
            letterSpacing: "-0.025em",
          })}
        >
          One session, four moves.
        </h2>

        <div
          ref={ref}
          className={css({
            position: "relative",
            display: "grid",
            gap: { base: "1.5rem", md: "1.25rem" },
            gridTemplateColumns: { base: "1fr", sm: "repeat(2, minmax(0, 1fr))", lg: "repeat(4, minmax(0, 1fr))" },
          })}
        >
          {/* The rule that stitches the beats together, drawn left to right. */}
          <span
            aria-hidden="true"
            className={css({
              position: "absolute",
              top: "1.15rem",
              left: 0,
              right: 0,
              height: "2px",
              display: { base: "none", lg: "block" },
              background:
                "repeating-linear-gradient(90deg, var(--ink) 0 8px, transparent 8px 16px)",
              transformOrigin: "left center",
              transform: revealed ? "scaleX(1)" : "scaleX(0)",
              transition: "transform 900ms cubic-bezier(0.22, 1, 0.36, 1)",
            })}
          />

          {JOURNEY.map((beat, index) => (
            <article
              key={beat.step}
              style={{ transitionDelay: revealed ? `${index * 110}ms` : "0ms" }}
              className={css({
                position: "relative",
                paddingTop: { base: 0, lg: "2.6rem" },
                opacity: revealed ? 1 : 0,
                transform: revealed ? "translateY(0)" : "translateY(14px)",
                transition: "opacity 520ms ease, transform 520ms cubic-bezier(0.16, 1, 0.3, 1)",
              })}
            >
              <span
                className={css({
                  position: { base: "static", lg: "absolute" },
                  top: 0,
                  left: 0,
                  display: "inline-grid",
                  placeItems: "center",
                  width: "2.3rem",
                  height: "2.3rem",
                  marginBottom: { base: "0.75rem", lg: 0 },
                  border: "2px solid var(--ink)",
                  background: "var(--paper)",
                  color: "var(--accent-dim)",
                  fontFamily: "var(--mono-body)",
                  fontSize: "0.7rem",
                  fontWeight: 700,
                  _dark: { color: "var(--phosphor)" },
                })}
              >
                {beat.step}
              </span>
              <h3
                className={css({
                  margin: "0 0 0.4rem",
                  fontFamily: "var(--mono-display)",
                  fontSize: { base: "1.15rem", md: "1.3rem" },
                  letterSpacing: "-0.01em",
                })}
              >
                {beat.title}
              </h3>
              <p
                className={css({
                  margin: 0,
                  maxWidth: "30ch",
                  color: "var(--ink-soft)",
                  fontSize: "0.92rem",
                  lineHeight: 1.65,
                })}
              >
                {beat.body}
              </p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

/* ------------------------------------------------------------------ *
 * CRT playthrough
