const FRAMES = [
  { id: "verse", label: "Verse", caption: "Contribute a verse.", kind: "quote" as const },
  {
    id: "web",
    label: "Web",
    caption: "The classroom keeps the question and the probe together.",
    kind: "image" as const,
    src: "/tapes/posters/web-classroom.jpg",
    alt: "Keating web classroom with a learner response and guided question",
  },
  {
    id: "tui",
    label: "TUI",
    caption: "The same dialogue, carried into the terminal.",
    kind: "image" as const,
    src: "/tapes/posters/tui-collaborative.jpg",
    alt: "Keating collaborative terminal teaching session",
  },
  {
    id: "cli",
    label: "CLI",
    caption: "Lessons leave plans, maps, and traces behind.",
    kind: "image" as const,
    src: "/tapes/posters/cli-artifacts.jpg",
    alt: "Keating CLI generating lesson artifacts",
  },
  {
    id: "review",
    label: "Review",
    caption: "Due work collects itself into a return path.",
    kind: "image" as const,
    src: "/tapes/posters/feature-coming-up.jpg",
    alt: "Keating Coming Up page with review priorities",
  },
  {
    id: "courses",
    label: "Courses",
    caption: "A course keeps the room intact between sessions.",
    kind: "image" as const,
    src: "/tapes/posters/feature-courses.jpg",
    alt: "Keating course page with lesson content and course tools",
  },
] as const;

export function CrtPlaythrough() {
  const reducedMotion = useReducedMotion();
  const sectionRef = useRef<HTMLElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [sectionVisible, setSectionVisible] = useState(false);
  const [pausedByInteraction, setPausedByInteraction] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);
  const [failedImages, setFailedImages] = useState<Set<string>>(() => new Set());
  const activeFrame = FRAMES[activeIndex];
  const effectivelyPlaying =
    playing && sectionVisible && pageVisible && !pausedByInteraction && !reducedMotion;

  useEffect(() => {
    setPlaying(!reducedMotion);
  }, [reducedMotion]);

  useEffect(() => {
    const update = () => setPageVisible(!document.hidden);
    update();
    document.addEventListener("visibilitychange", update);
    return () => document.removeEventListener("visibilitychange", update);
  }, []);

  useEffect(() => {
    const section = sectionRef.current;
    if (!section) return;
    if (!("IntersectionObserver" in window)) {
      setSectionVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setSectionVisible(entry.isIntersecting),
      { rootMargin: "-10% 0px", threshold: 0.15 },
    );
    observer.observe(section);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!effectivelyPlaying) return;
    const timer = window.setInterval(() => {
      setActiveIndex((current) => (current + 1) % FRAMES.length);
    }, 5800);
    return () => window.clearInterval(timer);
  }, [effectivelyPlaying]);

  function selectFrame(index: number) {
    setActiveIndex((index + FRAMES.length) % FRAMES.length);
    setPlaying(false);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      selectFrame(activeIndex + 1);
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      selectFrame(activeIndex - 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      selectFrame(0);
    } else if (event.key === "End") {
      event.preventDefault();
      selectFrame(FRAMES.length - 1);
    }
  }

  return (
    <section
      ref={sectionRef}
      id="crt"
      aria-labelledby="crt-title"
      className={css({
        paddingBlock: { base: "4rem", md: "6.5rem" },
        borderBottom: "2px solid var(--ink)",
        background:
          "radial-gradient(circle at 50% 48%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 28rem), var(--paper-deep)",
      })}
    >
      <div className="wrap">
        <h2
          id="crt-title"
          className={css({
            maxWidth: "24ch",
            margin: { base: "0 auto 2rem", md: "0 auto 3rem" },
            fontFamily: "var(--mono-display)",
            fontWeight: 700,
            fontSize: { base: "1.9rem", md: "2.9rem" },
            lineHeight: 1.04,
            letterSpacing: "-0.03em",
            textAlign: "center",
          })}
        >
          The verse, then the work.
        </h2>

        <figure
          className={css({ margin: 0 })}
          onPointerEnter={() => setPausedByInteraction(true)}
          onPointerLeave={() => setPausedByInteraction(false)}
          onFocusCapture={() => setPausedByInteraction(true)}
          onBlurCapture={(event) => {
            if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
              setPausedByInteraction(false);
            }
          }}
        >
          <div
            role="region"
            aria-label="Keating CRT screenshot playthrough"
            tabIndex={0}
            onKeyDown={handleKeyDown}
            className={css({
              _focusVisible: { outline: "3px solid var(--accent)", outlineOffset: "8px" },
            })}
          >
            <div className={cx("crt-wrap", css({ maxWidth: "820px" }))}>
              <img src="/brand/crt-monitor.png" alt="" aria-hidden="true" width={573} height={436} />
              <div
                className={cx(
                  "crt-screen",
                  css({
                    padding: 0,
                    borderRadius: "9% / 13%",
                    background: "#061009",
                    isolation: "isolate",
                    "&::before": {
                      content: '""',
                      position: "absolute",
                      inset: 0,
                      zIndex: 4,
                      background:
                        "radial-gradient(ellipse at center, transparent 45%, rgba(0, 0, 0, 0.5) 100%)",
                      pointerEvents: "none",
                    },
                  }),
                )}
              >
                {FRAMES.map((frame, index) => {
                  const active = index === activeIndex;
                  const failed = frame.kind === "image" && failedImages.has(frame.id);
                  return (
                    <div
                      key={frame.id}
                      aria-hidden={!active}
                      className={css({
                        position: "absolute",
                        inset: 0,
                        zIndex: active ? 2 : 1,
                        display: "grid",
                        placeItems: "center",
                        opacity: active ? 1 : 0,
                        transform: active ? "scale(1)" : "scale(1.025)",
                        filter: active ? "blur(0) saturate(0.86)" : "blur(4px) saturate(0.7)",
                        transition: reducedMotion
                          ? "none"
                          : "opacity 320ms ease, transform 480ms cubic-bezier(0.16, 1, 0.3, 1), filter 380ms ease",
                        pointerEvents: "none",
                      })}
                    >
                      {frame.kind === "quote" ? (
                        <blockquote
                          className={css({
                            display: "grid",
                            gap: "0.75rem",
                            width: "100%",
                            minHeight: "100%",
                            margin: 0,
                            padding: "8% 9%",
                            placeContent: "center",
                            color: "var(--phosphor)",
                            textAlign: "center",
                            textShadow: "0 0 14px rgba(75, 227, 136, 0.58)",
                          })}
                        >
                          <p
                            className={css({
                              margin: 0,
                              fontFamily: "var(--mono-display)",
                              fontSize: { base: "0.8rem", md: "1.35rem" },
                              fontStyle: "italic",
                              fontWeight: 700,
                              lineHeight: 1.45,
                            })}
                          >
                            &quot;That the powerful play goes on, and you may contribute a
                            verse.&quot;
                          </p>
                          <cite
                            className={css({
                              color: "var(--phosphor-dim)",
                              fontSize: { base: "0.42rem", md: "0.62rem" },
                              fontStyle: "normal",
                              letterSpacing: "0.14em",
                              textTransform: "uppercase",
                            })}
                          >
                            Walt Whitman // O Me! O Life!
                          </cite>
                        </blockquote>
                      ) : failed ? (
                        <div
                          className={css({
                            display: "grid",
                            gap: "0.5rem",
                            padding: "10%",
                            color: "var(--phosphor)",
                            fontSize: "0.65rem",
                            textAlign: "center",
                          })}
                        >
                          <strong className={css({ color: "var(--amber)" })}>
                            SCREEN SIGNAL LOST
                          </strong>
                          <span>{frame.caption}</span>
                        </div>
                      ) : (
                        <img
                          src={frame.src}
                          alt={active ? frame.alt : ""}
                          loading="lazy"
                          decoding="async"
                          className={css({
                            display: "block",
                            width: "100%",
                            height: "100%",
                            objectFit: "cover",
                            objectPosition: "top center",
                          })}
                          onError={() =>
                            setFailedImages((current) => {
                              const next = new Set(current);
                              next.add(frame.id);
                              return next;
                            })
                          }
                        />
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          <figcaption
            className={css({
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexWrap: "wrap",
              gap: "0.5rem",
              maxWidth: "820px",
              margin: { base: "1.5rem auto 0", md: "2rem auto 0" },
            })}
          >
            <span
              aria-live={playing ? "off" : "polite"}
              className={css({
                flex: "1 1 100%",
                marginBottom: "0.6rem",
                color: "var(--ink-soft)",
                fontFamily: "var(--mono-body)",
                fontSize: { base: "0.78rem", md: "0.85rem" },
                textAlign: "center",
              })}
            >
              <span className={css({ color: "var(--accent-dim)", _dark: { color: "var(--phosphor)" } })}>
                {String(activeIndex + 1).padStart(2, "0")}/{String(FRAMES.length).padStart(2, "0")}
              </span>{" "}
              {activeFrame.caption}
            </span>

            <button
              type="button"
              onClick={() => selectFrame(activeIndex - 1)}
              className={controlClass}
              aria-label="Previous CRT frame"
            >
              ←
            </button>
            {FRAMES.map((frame, index) => (
              <button
                key={frame.id}
                type="button"
                onClick={() => selectFrame(index)}
                aria-label={`Show ${frame.label} frame`}
                aria-pressed={index === activeIndex}
                className={css({
                  minWidth: { base: "2.25rem", md: "auto" },
                  minHeight: "2.25rem",
                  border: "1.5px solid var(--ink)",
                  background: index === activeIndex ? "var(--ink)" : "transparent",
                  color: index === activeIndex ? "var(--paper)" : "var(--ink)",
                  padding: { base: "0.45rem", md: "0.45rem 0.7rem" },
                  cursor: "pointer",
                  fontFamily: "var(--mono-body)",
                  fontSize: "0.58rem",
                })}
              >
                <span className={css({ display: { base: "none", md: "inline" } })}>
                  {frame.label}
                </span>
                <span className={css({ display: { base: "inline", md: "none" } })}>{index + 1}</span>
              </button>
            ))}
            {!reducedMotion && (
              <button
                type="button"
                onClick={() => setPlaying((current) => !current)}
                className={controlClass}
                aria-label={playing ? "Pause CRT playthrough" : "Play CRT playthrough"}
                aria-pressed={playing}
              >
                {playing ? "Ⅱ" : "▶"}
              </button>
            )}
            <button
              type="button"
              onClick={() => selectFrame(activeIndex + 1)}
              className={controlClass}
              aria-label="Next CRT frame"
            >
              →
            </button>
          </figcaption>
        </figure>
      </div>
    </section>
  );
}

const controlClass = css({
  minWidth: "2.25rem",
  minHeight: "2.25rem",
  border: "1.5px solid var(--ink)",
  background: "transparent",
  color: "var(--ink)",
  cursor: "pointer",
  fontFamily: "var(--mono-body)",
  _hover: { background: "var(--ink)", color: "var(--paper)" },
  _focusVisible: { outline: "3px solid var(--accent)", outlineOffset: "2px" },
});

