                </div>
                <ul className={heroProof} aria-label="Keating product qualities">
                  <li>Browser and terminal</li>
                  <li>Local-first CLI</li>
                  <li>Inspectable artifacts</li>
                </ul>
              </div>

              <div className="hero-stage">
                <HeroWonderStage>
                  <HeroTerminal />
                </HeroWonderStage>
              </div>
            </div>
