          <SurfaceScreencasts />
        </div>
        <KineticTeachingText />
        <LearningJourney />
        <CrtPlaythrough />

        {/* CLI surface */}
        <section className="use" id="use">
          <div className="wrap">
            <h2 className={sectionTitle()}>Everything you can run.</h2>
            <p className={sectionLede()}>
