                  <div className="use-cmds">
                    {group.commands.map((c) => (
                      <div className="use-cmd" key={c.cmd}>
                        <code>
                          <span>$ keating</span> {c.cmd}
                        </code>
                        <small>{c.desc}</small>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <div className="use-links">
              <button
                className={btnRetro({ tone: "primary" })}
