                className={cx(
                  "thought",
                  css({ top: "12%", left: { base: "-8%", md: "-24%" }, animationDelay: "0s" }),
                )}
                aria-hidden="true"
              >
                What makes you think that?
              </span>
              <span
                className={cx(
                  "thought",
                  css({ top: "40%", right: { base: "-6%", md: "-20%" }, animationDelay: "1.4s" }),
                )}
                aria-hidden="true"
              >
                Show me the mechanism.
              </span>
              <img
                className="final-bot"
                src="/brand/mascot-lotus.png"
                alt="Keating robot mascot"
                aria-hidden="true"
                width={300}
                height={426}
              />
            </div>
            <h2>Ready to think for yourself?</h2>
            <p>
              Bring a topic you half-understand. Keating will help you find the part that is not
              yours yet.
            </p>
            <div className="hero-ctas">
              <button
                className={btnRetro({ tone: "primary" })}
                onClick={() => {
                  posthog.capture("start_session_clicked", { source: "landing_final_cta" });
                  navigate({ to: "/chat" });
                }}
              >
                Start a session →
