/**
 * Minimal CDP screenshotter: launches chrome-headless-shell, loads a URL, and
 * writes one full-page capture plus a viewport capture per scroll step.
 *
 * usage: bun shot.ts <url> <outPrefix> [width] [height] [steps]
 */
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const CHROME =
  "/home/diogenes/.cache/puppeteer/chrome-headless-shell/linux-148.0.7778.97/chrome-headless-shell-linux64/chrome-headless-shell";

const url = process.argv[2] ?? "http://localhost:3000/";
const prefix = process.argv[3] ?? "shot";
const width = Number(process.argv[4] ?? 1440);
const height = Number(process.argv[5] ?? 900);
const steps = Number(process.argv[6] ?? 0);
const port = 9333 + Math.floor(Math.random() * 200);

const chrome = spawn(
  CHROME,
  [
    `--remote-debugging-port=${port}`,
    "--no-sandbox",
    "--disable-dev-shm-usage",
    "--hide-scrollbars",
    "--enable-unsafe-swiftshader",
    "--force-color-profile=srgb",
    `--window-size=${width},${height}`,
    "about:blank",
  ],
  { stdio: "ignore" },
);

let socket: WebSocket | undefined;
let nextId = 1;
const pending = new Map<number, (value: any) => void>();

function send(method: string, params: Record<string, unknown> = {}): Promise<any> {
  const id = nextId++;
  socket!.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve) => pending.set(id, resolve));
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function main() {
  // Wait for the debugger endpoint.
  let target: any;
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/new?${encodeURIComponent(url)}`, {
        method: "PUT",
      });
      if (res.ok) {
        target = await res.json();
        break;
      }
    } catch {
      /* not up yet */
    }
    await sleep(250);
  }
  if (!target) throw new Error("chrome did not start");

  socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket!.onopen = resolve;
    socket!.onerror = reject;
  });
  socket.onmessage = (event) => {
    const msg = JSON.parse(String(event.data));
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)!(msg.result);
      pending.delete(msg.id);
    }
  };

  await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", {
    width,
    height,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await send("Page.navigate", { url });
  await sleep(6000);

  const capture = async (name: string, extra: Record<string, unknown> = {}) => {
    const result = await send("Page.captureScreenshot", { format: "png", ...extra });
    writeFileSync(`${prefix}-${name}.png`, Buffer.from(result.data, "base64"));
    console.log(`wrote ${prefix}-${name}.png`);
  };

  const metrics = await send("Page.getLayoutMetrics");
  const content = metrics.cssContentSize ?? metrics.contentSize;
  console.log("page height:", content.height);

  await capture("full", {
    captureBeyondViewport: true,
    clip: { x: 0, y: 0, width, height: Math.min(content.height, 20000), scale: 0.4 },
  });

  for (let i = 0; i < steps; i++) {
    const y = Math.round((i * (content.height - height)) / Math.max(steps - 1, 1));
    await send("Runtime.evaluate", { expression: `window.scrollTo(0, ${y})` });
    await sleep(1400);
    await capture(`s${i}`);
  }

  chrome.kill();
  process.exit(0);
}

main().catch((error) => {
  console.error(error);
  chrome.kill();
  process.exit(1);
});

