"""Replay codex apply_patch payloads onto a scratch tree to recover the
pre-minimisation state of the landing page files."""
import os
import re
import sys

SCRATCH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "replay")
PATCH_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "patches")
REPO = "/home/diogenes/Projects/keating"


def split_sections(body):
    """Yield (action, path, lines) for each file section in a patch body."""
    lines = body.split("\n")
    i = 0
    sections = []
    while i < len(lines):
        line = lines[i]
        m = re.match(r"\*\*\* (Add|Update|Delete) File: (.+)", line)
        if m:
            action, path = m.group(1), m.group(2).strip()
            i += 1
            chunk = []
            while i < len(lines):
                if re.match(r"\*\*\* (Add|Update|Delete) File: ", lines[i]) or lines[i].startswith(
                    "*** End Patch"
                ):
                    break
                chunk.append(lines[i])
                i += 1
            sections.append((action, path, chunk))
            continue
        i += 1
    return sections


def apply_update(original, chunk):
    """Apply one Update File section's hunks to `original` (list of lines)."""
    out = list(original)
    # Split the chunk into hunks on '@@' markers.
    hunks = []
    current = None
    for line in chunk:
        if line.startswith("@@"):
            if current is not None:
                hunks.append(current)
            current = []
            continue
        if line.startswith("*** End of File"):
            continue
        if current is None:
            current = []
        current.append(line)
    if current:
        hunks.append(current)

    cursor = 0
    for hunk in hunks:
        old, new = [], []
        for line in hunk:
            if line.startswith("+"):
                new.append(line[1:])
            elif line.startswith("-"):
                old.append(line[1:])
            else:
                text = line[1:] if line.startswith(" ") else line
                old.append(text)
                new.append(text)
        while old and old[-1] == "" and (not new or new[-1] == ""):
            # trailing blank context on both sides is ambiguous; drop it
            old.pop()
            if new:
                new.pop()
        if not old:
            raise SystemExit("hunk with no old content")
        index = find(out, old, cursor)
        if index < 0:
            index = find(out, old, 0)
        if index < 0:
            raise SystemExit("could not locate hunk starting: %r" % old[:3])
        out[index : index + len(old)] = new
        cursor = index + len(new)
    return out


def find(haystack, needle, start):
    for i in range(start, len(haystack) - len(needle) + 1):
        if haystack[i : i + len(needle)] == needle:
            return i
    return -1


def main():
    names = sorted(os.listdir(PATCH_DIR))
    for name in names:
        body = open(os.path.join(PATCH_DIR, name)).read()
        for action, path, chunk in split_sections(body):
            rel = os.path.relpath(path, REPO)
            target = os.path.join(SCRATCH, rel)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            if action == "Delete":
                if os.path.exists(target):
                    os.remove(target)
                print(f"{name}: delete {rel}")
                continue
            if action == "Add":
                content = "\n".join(l[1:] if l.startswith("+") else l for l in chunk)
                open(target, "w").write(content.rstrip("\n") + "\n")
                print(f"{name}: add {rel}")
                continue
            if not os.path.exists(target):
                print(f"{name}: SKIP update, no base for {rel}")
                continue
            original = open(target).read().split("\n")
            try:
                updated = apply_update(original, chunk)
            except SystemExit as error:
                print(f"{name}: FAILED {rel}: {error}")
                sys.exit(1)
            open(target, "w").write("\n".join(updated))
            print(f"{name}: update {rel}")


if __name__ == "__main__":
    main()

