export function CrtPlaythrough() {
  const reducedMotion = useReducedMotion();
  const sectionRef = useRef<HTMLElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [hoverPaused, setHoverPaused] = useState(false);
  const [focusPaused, setFocusPaused] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);
  const [sectionVisible, setSectionVisible] = useState(false);
  const [failedImages, setFailedImages] = useState<Set<string>>(() => new Set());
  const activeFrame = CRT_FRAMES[activeIndex];
  const effectivelyPlaying =
    isPlaying && !hoverPaused && !focusPaused && pageVisible && sectionVisible;

  useEffect(() => {
    setIsPlaying(!reducedMotion);
  }, [reducedMotion]);

  useEffect(() => {
    const updateVisibility = () => setPageVisible(!document.hidden);
    updateVisibility();
    document.addEventListener("visibilitychange", updateVisibility);
    return () => document.removeEventListener("visibilitychange", updateVisibility);
  }, []);

  useEffect(() => {
    const section = sectionRef.current;
    if (!section) return;
    if (!("IntersectionObserver" in window)) {
      setSectionVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setSectionVisible(entry.isIntersecting),
      { rootMargin: "-10% 0px", threshold: 0.12 },
    );
    observer.observe(section);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (reducedMotion || !effectivelyPlaying) return;
    const timer = window.setInterval(() => {
      setActiveIndex((current) => (current + 1) % CRT_FRAMES.length);
    }, 5600);
    return () => window.clearInterval(timer);
  }, [effectivelyPlaying, reducedMotion]);

  function selectFrame(index: number, manual = true) {
    const normalized = (index + CRT_FRAMES.length) % CRT_FRAMES.length;
    setActiveIndex(normalized);
    if (manual) setIsPlaying(false);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      selectFrame(activeIndex + 1);
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      selectFrame(activeIndex - 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      selectFrame(0);
    } else if (event.key === "End") {
      event.preventDefault();
      selectFrame(CRT_FRAMES.length - 1);
    }
  }

  return (
    <section
      ref={sectionRef}
      className="crt-playthrough"
      aria-labelledby="crt-playthrough-title"
    >
      <div className="wrap crt-playthrough-heading">
        <div>
