        className="wrap crt-program-layout"
        role="region"
        aria-label="Keating CRT image playthrough"
        tabIndex={0}
        onKeyDown={handleKeyDown}
        onPointerEnter={() => setHoverPaused(true)}
        onPointerLeave={() => setHoverPaused(false)}
        onFocusCapture={() => setFocusPaused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
            setFocusPaused(false);
          }
        }}

        }}
      >
        <div className="crt-program-stage">
          <div className="crt-wrap">
            <img src="/brand/crt-monitor.png" alt="" aria-hidden="true" width={573} height={436} />
            <div className="crt-screen crt-program-screen">
              {CRT_FRAMES.map((frame, index) => {
                const active = index === activeIndex;
                const failed = frame.kind === "image" && failedImages.has(frame.id);
                return (
                  <div
                    key={frame.id}
                    className={`crt-program-frame${active ? " is-active" : ""}`}
                    aria-hidden={!active}
                  >
                    {frame.kind === "quote" ? (
                      <blockquote className="crt-program-quote">
                        <p>
                          &quot;That the powerful play goes on, and you may contribute a verse.&quot;
                        </p>
                        <cite>Walt Whitman // O Me! O Life!</cite>
                      </blockquote>
                    ) : failed ? (
                      <div className="crt-program-fallback">
                        <strong>SCREEN SIGNAL LOST</strong>
                        <span>{frame.title}</span>
                      </div>
                    ) : (
                      <img
                        src={frame.src}
                        alt={active ? frame.alt : ""}
                        loading="lazy"
                        decoding="async"
                        style={{ objectPosition: frame.objectPosition }}
                        onError={() =>
                          setFailedImages((current) => {
                            const next = new Set(current);
                            next.add(frame.id);
                            return next;
                          })
                        }
                      />
                    )}
                  </div>
                );
              })}
