              {reducedMotion ? "MANUAL" : effectivelyPlaying ? "PLAY" : "PAUSE"}
            </span>
          </div>
          <div aria-live={isPlaying ? "off" : "polite"}>
            <div className="crt-program-label">{activeFrame.label}</div>
            <h3>{activeFrame.title}</h3>
            <p>{activeFrame.description}</p>
          </div>

